package com.google.javascript.rhino;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.base.Objects;
import com.google.common.base.Preconditions;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.SimpleSourceFile;
import com.google.javascript.rhino.jstype.StaticSourceFile;
import java.io.*;
import java.io.IOException;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class Node_copyInformationFrom_TriageGen1Test {

    // Constants based on the method logic provided
    private static final int ORIGINALNAME_PROP = 1; // Assuming 1 for testing purposes
    private static final int STATIC_SOURCE_FILE = 2; // Assuming 2 for testing purposes

    /**
     * Test case where the target node (this) has no properties set.
     * Should copy both ORIGINALNAME_PROP and STATIC_SOURCE_FILE/sourcePosition.
     */
    @Test
    public void testCopyWhenTargetIsEmpty() {
        Node target = new Node(0);
        Node source = new Node(0);

        String originalName = "originalName";
        Object staticSourceFile = new Object(); // Mocking StaticSourceFile
        int sourcePosition = 123;

        source.putProp(ORIGINALNAME_PROP, originalName);
        source.putProp(STATIC_SOURCE_FILE, staticSourceFile);
        source.setSourceEncodedPosition(sourcePosition); // Assuming sourcePosition is set via this

        // Since sourcePosition is a field, we use the setter/getter logic provided in API
        // Note: The method uses target.sourcePosition = other.sourcePosition directly.
        // We will use the setter provided in the class to simulate the field state.
        source.setSourceEncodedPosition(sourcePosition);

        Node result = target.copyInformationFrom(source);

        // Verify return value is 'this'
        assertSame(target, result);

        // Verify properties copied
        assertEquals(originalName, target.getProp(ORIGINALNAME_PROP));
        assertEquals(staticSourceFile, target.getProp(STATIC_SOURCE_FILE));
        assertEquals(sourcePosition, target.getSourceEncodedPosition());
    }

    /**
     * Test case where target ALREADY has ORIGINALNAME_PROP.
     * Should NOT overwrite the existing property.
     */
    @Test
    public void testCopyWhenOriginalNameExists() {
        Node target = new Node(0);
        Node source = new Node(0);

        String existingName = "existing";
        String newName = "new";

        target.putProp(ORIGINALNAME_PROP, existingName);
        source.putProp(ORIGINALNAME_PROP, newName);

        target.copyInformationFrom(source);

        // Should retain the old value
        assertEquals(existingName, target.getProp(ORIGINALNAME_PROP));
    }

    /**
     * Test case where target ALREADY has STATIC_SOURCE_FILE.
     * Should NOT overwrite the existing property or sourcePosition.
     */
    @Test
    public void testCopyWhenStaticSourceFileExists() {
        Node target = new Node(0);
        Node source = new Node(0);

        Object existingFile = new Object();
        Object newFile = new Object();
        int existingPos = 10;
        int newPos = 20;

        target.putProp(STATIC_SOURCE_FILE, existingFile);
        target.setSourceEncodedPosition(existingPos);

        source.putProp(STATIC_SOURCE_FILE, newFile);
        source.setSourceEncodedPosition(newPos);

        target.copyInformationFrom(source);

        // Should retain existing values
        assertEquals(existingFile, target.getProp(STATIC_SOURCE_FILE));
        assertEquals(existingPos, target.getSourceEncodedPosition());
    }

    /**
     * Test case where ORIGINALNAME_PROP is null in source.
     * Should result in target having null for that property.
     */
    @Test
    public void testCopyWhenSourcePropIsNull() {
        Node target = new Node(0);
        Node source = new Node(0);

        // Source has no ORIGINALNAME_PROP set
        assertNull(source.getProp(ORIGINALNAME_PROP));

        target.copyInformationFrom(source);

        assertNull(target.getProp(ORIGINALNAME_PROP));
    }

    /**
     * Test case where target has ORIGINALNAME_PROP but lacks STATIC_SOURCE_FILE.
     * Should copy only the static source info.
     */
    @Test
    public void testCopyPartial() {
        Node target = new Node(0);
        Node source = new Node(0);

        target.putProp(ORIGINALNAME_PROP, "stay");

        source.putProp(STATIC_SOURCE_FILE, "sourceFile");
        source.setSourceEncodedPosition(55);

        target.copyInformationFrom(source);

        assertEquals("stay", target.getProp(ORIGINALNAME_PROP));
        assertEquals("sourceFile", target.getProp(STATIC_SOURCE_FILE));
        assertEquals(55, target.getSourceEncodedPosition());
    }
}
